/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

import type { ReactNode } from "react";

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** A headline figure given as a number, so its digits roll when it changes. */
export interface StatFigureRoll {
  /** The number to show. Round it first when the figure is a whole number. */
  value: number;
  /** A module-level constant, never an inline object: the ticker memoises its formatter on it. */
  format: Intl.NumberFormatOptions;
  /** Text before the number with no space, such as a sign. */
  prefix?: string;
  /** Text after the number with no space, such as "%". */
  suffix?: string;
  /** A word after the number, with a space before it, such as "messages". */
  unit?: string;
}

/** Props for one headline figure. */
export interface StatFigureProps {
  label: string;
  /** The figure as ready text. Leave it out when `roll` is set. */
  value?: ReactNode;
  /** The figure as a number whose digits roll on change. It takes the place of `value`. */
  roll?: StatFigureRoll;
  /** A change figure or a short note under the value. */
  children?: ReactNode;
  className?: string;
}

/** One headline figure with its name and a note. Place it inside a `dl`. */
export function StatFigure({ label, value, roll, children, className }: StatFigureProps) {
  return (
    <div className={cn("flex min-w-0 flex-col gap-1 bg-card px-5 py-4", className)}>
      <dt className="truncate text-sm text-muted-foreground">{label}</dt>
      <dd className="text-2xl font-semibold tracking-tight tabular-nums">
        {roll ? (
          <>
            {roll.prefix}
            <NumberTicker value={roll.value} format={roll.format} />
            {roll.suffix}
            {roll.unit ? ` ${roll.unit}` : null}
          </>
        ) : (
          value
        )}
      </dd>
      {children ? <dd className="flex min-w-0 items-center gap-x-2 overflow-hidden text-xs whitespace-nowrap text-muted-foreground">{children}</dd> : null}
    </div>
  );
}

"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { useState } from "react";

import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { cn } from "@/lib/utils";

import { PointTip, type PointTipProps } from "../../parts/point-tip";
import type { BridgeStep, MoveKind } from "./data";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for the bridge chart. */
export interface BridgeChartProps {
  /** Names the group of bars for screen readers. */
  label: string;
  steps: BridgeStep[];
  /** The values at the two ends of the axis. The axis does not start at zero. */
  axis: { low: number; high: number; ticks: number[] };
  selected: MoveKind;
  onSelect: (kind: MoveKind) => void;
  /** The figure at the end of a row: a level for a total, a signed change for a move. */
  formatStep: (step: BridgeStep) => string;
  formatAxis: (level: number) => string;
  /** The details shown in the card beside the inspected bar. The rows are also read out with each change row. */
  stepDetails: (step: BridgeStep) => Pick<PointTipProps, "title" | "rows" | "note">;
}

// Critically damped: bars settle on their new levels with no wobble.
const MORPH: Transition = { type: "spring", stiffness: 280, damping: 34, mass: 1 };
const INSTANT: Transition = { duration: 0 };

const isMove = (id: BridgeStep["id"]): id is MoveKind => id !== "start" && id !== "end";

const FILL = {
  total: "fill-muted-foreground/60",
  gain: "fill-chart-2",
  loss: "fill-chart-3",
} satisfies Record<string, string>;

/**
 * A bridge drawn as rows: a start bar, one floating bar per kind of change,
 * and an end bar. The five change rows are one radio group, so they are one
 * tab stop: arrows move and wrap, Home and End jump, and each move selects.
 * The row under the pointer, or the row the keyboard is on, keeps its full
 * colour while the other bars fade, and a card shows its figures.
 */
export function BridgeChart({ label, steps, axis, selected, onSelect, formatStep, formatAxis, stepDetails }: BridgeChartProps) {
  const reduceMotion = useReducedMotion();
  const transition = reduceMotion ? INSTANT : MORPH;
  const [hovered, setHovered] = useState<BridgeStep["id"] | null>(null);
  const [keyboard, setKeyboard] = useState(false);
  const inspectedId = hovered ?? (keyboard ? selected : null);
  const inspectedRow = steps.findIndex((step) => step.id === inspectedId);
  const inspected = steps[inspectedRow];
  const kinds = steps.map((step) => step.id).filter(isMove);
  const rows = steps.length;
  const across = (level: number) => ((level - axis.low) / (axis.high - axis.low || 1)) * 100;
  const top = (row: number) => ((row + 0.24) / rows) * 100;
  const bottom = (row: number) => ((row + 0.76) / rows) * 100;
  const ends = (step: BridgeStep) => ({ low: across(Math.min(step.from, step.to)), high: across(Math.max(step.from, step.to)) });
  // The card hangs from the end of the bar with more room. It flips to the left of any point past 55.
  const tipX = (step: BridgeStep) => {
    const { low, high } = ends(step);
    return high > 55 ? Math.max(low, 55.5) : high;
  };

  return (
    <div className="flex flex-col gap-1">
      <div onPointerLeave={() => setHovered(null)} className="relative grid grid-cols-[6.5rem_1fr_5rem]">
      {/* Radix moves and wraps on the arrows, jumps on Home and End, and selects as it moves. */}
      <RadioGroup
        aria-label={label}
        value={selected}
        onValueChange={(value) => {
          const kind = kinds.find((item) => item === value);
          if (kind) onSelect(kind);
        }}
        onFocus={(event) => setKeyboard(event.target.matches(":focus-visible"))}
        onBlur={() => setKeyboard(false)}
        className="contents"
      >
        <div aria-hidden="true" className="pointer-events-none absolute inset-y-0 right-20 left-26">
          {axis.ticks.map((tick) => (
            <span key={tick} className="left-(--x) absolute inset-y-0 w-px bg-border/60" style={
              // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
              { "--x": `${across(tick)}%` } as VarStyle
            } />
          ))}
        </div>
        {steps.map((step) => {
          // With one row inspected, the other rows step back so the eye stays on it.
          const quiet = inspectedId !== null && step.id !== inspectedId;
          const tone = cn("motion-safe:transition-colors motion-safe:duration-150", quiet ? "text-muted-foreground" : undefined);
          const name = <span className={cn("truncate pl-3 text-sm", tone)}>{step.label}</span>;
          const figure = <span className={cn("pr-3 text-right text-sm tabular-nums", tone)}>{formatStep(step)}</span>;
          if (!isMove(step.id)) {
            return (
              <div key={step.id} onPointerEnter={() => setHovered(step.id)} className="col-span-3 grid h-11 grid-cols-subgrid items-center rounded-lg font-medium hover:bg-muted/40">
                {name}
                <span />
                {figure}
              </div>
            );
          }
          const kind = step.id;
          const checked = kind === selected;
          return (
            <label
              key={kind}
              onPointerEnter={() => setHovered(kind)}
              className={cn(
                "relative col-span-3 grid h-11 cursor-pointer grid-cols-subgrid items-center rounded-lg",
                "has-focus-visible:ring-2 has-focus-visible:ring-ring has-focus-visible:ring-inset",
                checked ? "bg-muted/70 font-medium" : "hover:bg-muted/40",
              )}
            >
              <RadioGroupItem value={kind} className="sr-only" />
              {checked ? <span aria-hidden="true" className="absolute inset-y-2 left-0 w-0.5 rounded-full bg-foreground" /> : null}
              {name}
              <span className="sr-only">
                {step.moves.length} {step.moves.length === 1 ? "account" : "accounts"}
                {stepDetails(step)
                  .rows.map((row) => `, ${row.label} ${row.value}`)
                  .join("")}
              </span>
              <span />
              {figure}
            </label>
          );
        })}
        <div aria-hidden="true" className="pointer-events-none absolute inset-y-0 right-20 left-26">
        <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="size-full overflow-visible">
          {steps.map((step, row) => {
            const { low, high } = ends(step);
            const tone = isMove(step.id) ? (step.value >= 0 ? "gain" : "loss") : "total";
            return (
              <motion.path
                key={step.id}
                initial={false}
                animate={{ d: `M${low.toFixed(2)} ${top(row).toFixed(2)} H${high.toFixed(2)} V${bottom(row).toFixed(2)} H${low.toFixed(2)} Z` }}
                transition={transition}
                className={cn(
                  FILL[tone],
                  "motion-safe:transition-opacity motion-safe:duration-150",
                  inspectedId !== null && step.id !== inspectedId ? "opacity-30" : "opacity-100",
                )}
              />
            );
          })}
          {steps.slice(0, -1).map((step, row) => (
            <motion.path
              key={step.id}
              initial={false}
              animate={{ d: `M${across(step.to).toFixed(2)} ${bottom(row).toFixed(2)} V${top(row + 1).toFixed(2)}` }}
              transition={transition}
              fill="none"
              strokeWidth="1"
              strokeDasharray="2 2"
              vectorEffect="non-scaling-stroke"
              className="stroke-muted-foreground"
            />
          ))}
        </svg>
        </div>
        {inspected ? (
          <div className="pointer-events-none absolute inset-y-0 right-20 left-26">
            <PointTip x={tipX(inspected)} y={((inspectedRow + 0.5) / rows) * 100} {...stepDetails(inspected)} />
          </div>
        ) : null}
      </RadioGroup>
      </div>
      <div aria-hidden="true" className="relative mr-20 ml-26 h-5 text-xs tabular-nums text-muted-foreground">
        {axis.ticks.map((tick, index) =>
          index % 2 === 0 ? (
            <span key={tick} className="left-(--x) absolute -translate-x-1/2" style={
              // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
              { "--x": `${across(tick)}%` } as VarStyle
            }>
              {formatAxis(tick)}
            </span>
          ) : null,
        )}
      </div>
    </div>
  );
}

