const MOVES: Move[] = ROWS.map(([month, kind, account, plan, amount]) => ({ month, kind, account, plan, amount }));

const total = (moves: Move[]) => sum(moves.map((move) => move.amount));

/**
 * The bridge for one period. Every step is the sum of its accounts, and each
 * step starts where the one before ended, so start plus the steps is the end.
 */
export function readPeriod(id: PeriodId) {
  const period = PERIODS.find((item) => item.value === id) ?? PERIODS[0]!;
  const firstMonth = period.months[0] ?? 0;
  const start = OPENING + total(MOVES.filter((move) => move.month < firstMonth));
  const inPeriod = MOVES.filter((move) => period.months.includes(move.month));

  let level = start;
  const changes: BridgeStep[] = KINDS.map((kind) => {
    const moves = inPeriod.filter((move) => move.kind === kind.id).sort((a, b) => Math.abs(b.amount) - Math.abs(a.amount));
    const value = total(moves);
    const from = level;
    level += value;
    return { id: kind.id, label: kind.label, from, to: level, value, moves };
  });
  const end = level;
  const levels = [start, end, ...changes.map((step) => step.to)];
  const spread = niceScale(Math.min(...levels), Math.max(...levels));
  // One step of room below the lowest level, so the shortest total bar still shows.
  const axis = niceScale(spread.low - spread.step, spread.high);

  const by = (kind: MoveKind) => changes.find((step) => step.id === kind)?.value ?? 0;
  const gained = by("added") + by("expansion") + by("reactivation");
  const lost = by("contraction") + by("churn");
  const steps: BridgeStep[] = [
    { id: "start", label: "Start", from: axis.low, to: start, value: start, moves: [] },
    ...changes,
    { id: "end", label: "End", from: axis.low, to: end, value: end, moves: [] },
  ];

  return {
    period,
    start,
    end,
    steps,
    axis,
    gained,
    lost,
    netRetention: ((start + by("expansion") + lost) / start) * 100,
    grossRetention: ((start + lost) / start) * 100,
    quickRatio: lost === 0 ? 0 : gained / Math.abs(lost),
  };
}

/** An axis that starts and ends on round values, with a tick at every step between. */
export interface NiceScale {
  low: number;
  high: number;
  step: number;
  ticks: number[];
}

/** The nearest round step at or above `raw`: 1, 2, 2.5 or 5 times a power of ten. */
export function niceStep(raw: number): number {
  if (!(raw > 0)) return 1;
  const power = 10 ** Math.floor(Math.log10(raw));
  const factor = raw / power;
  const round = factor <= 1 ? 1 : factor <= 2 ? 2 : factor <= 2.5 ? 2.5 : factor <= 5 ? 5 : 10;
  return round * power;
}

/** A round axis that holds `low` to `high` in about `count` steps. */
export function niceScale(low: number, high: number, count = 4): NiceScale {
  const step = niceStep((high - low || 1) / count);
  const first = Math.floor(low / step);
  const last = Math.max(first + 1, Math.ceil(high / step));
  const ticks = Array.from({ length: last - first + 1 }, (_, index) => (first + index) * step);
  return { low: first * step, high: last * step, step, ticks };
}

